  receiverEntry: {family:'guide',min:-25,max:45,tolerance:2,coordinate:5,response:3},
  receiverTurn: {family:'guide',min:-90,max:90,tolerance:4,coordinate:10,response:6},
  receiverExit: {family:'guide',min:-100,max:100,tolerance:4,coordinate:10,response:6},
  receiverDuration: {family:'guide',min:.1,max:1,tolerance:.05,coordinate:.15,response:.08,searchDefault:()=>.65},
};
export const ARC_CONTROL_KEYS = Object.keys(ARC_CONTROL_DEFINITIONS) as readonly ControlKey[];
export const ARC_CORE_KEYS = ARC_CONTROL_KEYS.filter(key => ARC_CONTROL_DEFINITIONS[key].family === 'core');
export const ARC_EXPRESSIVE_KEYS = ARC_CONTROL_KEYS.filter(key => ARC_CONTROL_DEFINITIONS[key].family === 'expressive');
type ControlStyle = Pick<ArcControlContext, 'profile' | 'profileStrength' | 'profileStart' | 'railLayout' | 'independentGuide' | 'observedReceiver'>;

/** Disabled guides have no meaningful clearance, coverage or flare coordinates. */
export function arcControlActive(key:ControlKey,guides=true,style?:ControlStyle):boolean {
  // Transfer fulfillment currently specifies the forward support followed by
  // its separated receiver. An opposing opening uses the paired constructor.
  if(key==='contactSide')return style?.railLayout!=='transfer';
  if(key.startsWith('receiver'))return guides&&style?.observedReceiver===true&&style.railLayout==='transfer';
  if(key==='foldBias')return style?.profile==='fold'&&style.railLayout==='transfer'&&style.independentGuide===true;
  if(key==='foldTiming')return style?.profile==='fold'&&style?.independentGuide===true&&style?.railLayout==='transfer';
  if(key==='foldBend')return style?.profile==='fold'&&style?.independentGuide===true;
  if(key==='guideTilt')return guides&&style?.independentGuide===true;
  if(key==='mainEnd')return style?.railLayout==='transfer';
  // A full three-face fold replaces the entire smooth heading schedule.
  if(key==='bend'&&style?.profile==='fold'&&(style.profileStrength??1)===1&&style.profileStart===0)return false;
  return guides || (ARC_CONTROL_DEFINITIONS[key].family!=='guide' && key!=='guideFlare');
}

/** Resolve the interval's active fields once; candidate values remain independent.
 * Registry order keeps support normalized before dependent turn timing. */
export function arcControlNormalizer(input: ArcControlContext): (control: ArcMotionControl) => ArcMotionControl {
  const context = {...input};
  const active: {key: ControlKey; definition: ControlDefinition}[] = [], inactive: ControlKey[] = [];
  for (const key of ARC_CONTROL_KEYS) {
    if (arcControlActive(key, context.guides, context)) active.push({key, definition: ARC_CONTROL_DEFINITIONS[key]});
    else inactive.push(key);
  }
  return control => {
    const c = {...control};
    for (const key of inactive) delete c[key];
    for (const {key, definition} of active) {
      if (key === 'foldBend' && c[key] === undefined) c[key] = context.foldAngle ?? 50;
      const value = c[key];
      if (value === undefined && definition.family !== 'core') continue;
      c[key] = definition.normalize ? definition.normalize(value!, c, context) : clamp(value!, definition.min, definition.max);
    }
    return c;
  };
}

/** All other geometry inputs are fixed by the surrounding evaluation context.
 * Absence and signed zero are significant. Only implicit clearance is exactly
 * equivalent to the fixed channel, even when the search default would be 12.
 * Numeric strings contain no separator; the fixed field order distinguishes
 * absence, signed zero and every nonfinite value without JSON encoding. */
const keyProbe = (globalThis as any).__keyProbe = [];
export function arcControlMemoKey(c: ArcMotionControl, channel?: number): string {
  keyProbe.push({c:{...c},channel});
  return ARC_CONTROL_KEYS.map(key => {
    const value = key === 'clearance' ? c.clearance ?? channel ?? 0 : c[key];
    return value === undefined ? '' : Object.is(value, -0) ? '-0' : String(value);
  }).join('|');
}

export function arcControlValue(c: ArcMotionControl, key: ControlKey, channel?: number): number {
  return c[key] ?? ARC_CONTROL_DEFINITIONS[key].searchDefault?.(c, channel) ?? 0;
}

/** The step of `key` for `method`; support-scaled steps use the given support. */
export function arcControlStep(key: ControlKey, method: SearchMethod, support: number): number {
  const step = ARC_CONTROL_DEFINITIONS[key][method];
  if (step === undefined) throw new Error(`arc control ${key} has no ${method} step`);
  return typeof step === 'number' ? step : step(support);
}

/** The active controls that finite-difference response search adjusts. */
export function arcResponseKeys(guides = true, style?: ControlStyle): ControlKey[] {
  return ARC_CONTROL_KEYS.filter(key => arcControlActive(key, guides, style) && ARC_CONTROL_DEFINITIONS[key].response !== undefined);
}

export type ArcControlReference = {control: ArcMotionControl; incoming: number; span: number};

/** Preserve demonstrated doubles and field absence at the original boundary. */
export function arcReferencedControl(reference: ArcControlReference, incoming: number, span: number): ArcMotionControl {
  if (!Number.isFinite(reference.incoming) || !Number.isFinite(reference.span) || reference.span <= 0)
    throw new Error('invalid arc control reference');
  const c = reference.control, angle = incoming - reference.incoming;
  return {...c, entry: angle === 0 ? c.entry : c.entry + angle,
    exit: angle === 0 ? c.exit : c.exit + angle,
    support: span === reference.span ? c.support : c.support * (span / reference.span)};
}

/** A neighborhood in authored control space, not a physical-equivalence claim.
 * Keep distinct expressive shapes available to the real-engine evaluator.
 * Conservatively distinguish omitted optional fields: their defaults can depend
 * on the channel setting and explicit guide endpoints have a length floor. */
export function arcControlsSimilar(a: ArcMotionControl, b: ArcMotionControl): boolean {
  return ARC_CONTROL_KEYS.every(key => {
    const x = a[key], y = b[key];
    return x === undefined || y === undefined ? x === y : Math.abs(x - y) < ARC_CONTROL_DEFINITIONS[key].tolerance;
  });
}

