import {readFileSync,writeFileSync} from 'node:fs';
import {deserialize} from 'node:v8';
import assert from 'node:assert/strict';
import {ARC_CONTROL_KEYS,arcControlMemoKey} from './reference/scripts/v0/optimizer/arc_motion_control.ts';
const base='/tmp/engine-query-cost-20261106';
const inputs=deserialize(readFileSync(base+'/probe/key-inputs-61.v8'));
const numeric=(c:any,channel?:number)=>ARC_CONTROL_KEYS.map(key=>{
  const value=key==='clearance'?c.clearance??channel??0:c[key];
  return value===undefined?'':Object.is(value,-0)?'-0':value;
}).join('|');
const direct=(c:any,channel?:number)=>{
  let key='';
  for(let i=0;i<ARC_CONTROL_KEYS.length;i++){
    if(i)key+='|';
    const field=ARC_CONTROL_KEYS[i],value=field==='clearance'?c.clearance??channel??0:c[field];
    if(value!==undefined)key+=Object.is(value,-0)?'-0':String(value);
  }
  return key;
};
const methods={original:arcControlMemoKey,numeric,direct};
const values=[undefined,-Infinity,-Number.MAX_VALUE,-1e-200,-1,-0,0,1,1e-200,Number.MAX_VALUE,Infinity,NaN];
const cases=[...inputs];
for(const field of ARC_CONTROL_KEYS)for(const value of values)for(const channel of [undefined,-0,0,12,NaN])cases.push({c:{[field]:value},channel});
for(const {c,channel} of cases){
 for(const field of ARC_CONTROL_KEYS)assert(c[field]===undefined||typeof c[field]==='number');
 const expected=arcControlMemoKey(c,channel);
 assert.equal(numeric(c,channel),expected);assert.equal(direct(c,channel),expected);
}
const lookup=new Map(inputs.map(({c,channel}:any,i:number)=>[arcControlMemoKey(c,channel),i]));
const loops=Math.max(1,Math.floor(100000/inputs.length));let checksum=0;
function sample(method:keyof typeof methods){
 const fn=methods[method],start=performance.now();
 for(let rep=0;rep<loops;rep++)for(const {c,channel} of inputs)checksum+=lookup.get(fn(c,channel))!;
 return (performance.now()-start)*1e6/(loops*inputs.length);
}
for(let warm=0;warm<2;warm++)for(const method of Object.keys(methods))sample(method as keyof typeof methods);
const orders=[['original','numeric','direct'],['numeric','direct','original'],['direct','original','numeric'],['direct','numeric','original'],['numeric','original','direct'],['original','direct','numeric']];
const samples=orders.map(order=>order.map(method=>({method,nsPerKey:sample(method as keyof typeof methods)})));
const median=(values:number[])=>{const a=values.toSorted((a,b)=>a-b),n=a.length;return(a[(n-1)>>1]+a[n>>1])/2;};
const medians=Object.fromEntries(Object.keys(methods).map(method=>[method,median(samples.flat().filter(s=>s.method===method).map(s=>s.nsPerKey))]));
const result={scope:'Exploratory encoder plus Map lookup on captured default controls. Exact numeric/undefined contract and byte equality; not compiler timing.',cases:cases.length,inputs:inputs.length,loops,checksum,samples,medians,relative:Object.fromEntries(Object.entries(medians).map(([method,ns])=>[method,100*(ns/medians.original-1)]))};
writeFileSync(base+'/key-diagnostic.json',JSON.stringify(result,null,2)+'\n');console.log(result.medians,result.relative);

